css:
/* Guard against the storefront app's own base styles (its CSS reset sets fonts,
   line heights, list styles, link colours and image sizing on every page), so the
   utility bar, header and footer look the same on /store as on the rest of the site. */
[data-bz-section="utility-bar"], [data-bz-node="header"], [data-bz-section="site-footer"] { font-family: var(--font-body); font-size: var(--text-body); line-height: 1.6; color: #fff; text-align: left; -webkit-font-smoothing: antialiased; }
:is([data-bz-section="utility-bar"], [data-bz-node="header"], [data-bz-section="site-footer"]) *, :is([data-bz-section="utility-bar"], [data-bz-node="header"], [data-bz-section="site-footer"]) *::before, :is([data-bz-section="utility-bar"], [data-bz-node="header"], [data-bz-section="site-footer"]) *::after { box-sizing: border-box; }
:is([data-bz-section="utility-bar"], [data-bz-node="header"], [data-bz-section="site-footer"]) :is(ul, ol) { list-style: none; margin: 0; padding: 0; }
:is([data-bz-section="utility-bar"], [data-bz-node="header"], [data-bz-section="site-footer"]) a { text-decoration: none; }
:is([data-bz-section="utility-bar"], [data-bz-node="header"], [data-bz-section="site-footer"]) svg { display: inline-block; }
[data-bz-node="logo"] img { height: 40px; width: auto; max-width: none; display: block; }
[data-bz-node="ft-logo"] img { height: 48px; width: auto; max-width: none; display: block; }
[data-bz-section="site-footer"] .bz-section, [data-bz-node="header"].bz-section { background: var(--ink); }

/* Header, utility bar and footer. All chrome styling lives here because the
   /store inventory pages load the template CSS but not component CSS or
   section settings; keeping it in one place makes them match the rest of the site. */

/* Section settings mirrored from the canvas (utility bar fill, header and utility padding) */
[data-bz-node="ub"][data-bz-node] { padding: 9px 24px; background: var(--ink-dark); }
@media (max-width: 1100px) { html [data-bz-node="header"][data-bz-node] { padding-left: 24px; padding-right: 24px; } }
[data-bz-node="main-nav"] .bz-menu-wrap { justify-content: flex-end; }

/* Header */
[data-bz-node="header"] .bz-block { padding-block: 0; }
@media (max-width: 640px) { [data-bz-node="header-brand"] { grid-column: span 9; } [data-bz-node="header-nav"] { grid-column: span 3; } [data-bz-node="logo"] img { height: 34px; width: auto; } }

/* Utility bar */
[data-bz-section="utility-bar"] .bz-block { padding-block: 0; }
[data-bz-section="utility-bar"] .bz-block p { margin: 0; font-size: 13px; line-height: 1.4; color: rgba(255,255,255,.72); }
[data-bz-section="utility-bar"] .bz-block p a { color: #fff; font-weight: 700; text-decoration: none; margin-right: 14px; }
[data-bz-section="utility-bar"] .bz-nav { gap: 22px; flex-wrap: nowrap; }
[data-bz-section="utility-bar"] .bz-navitem > a { font: 500 13px / 1.4 var(--font-body); padding-block: 0; color: rgba(255,255,255,.85); }
[data-bz-section="utility-bar"] .bz-navitem > a:hover { color: #fff; }
[data-bz-section="utility-bar"] .bz-col[data-bz-node="ub-right"] { display: flex; align-items: center; justify-content: flex-end; gap: 22px; }
[data-bz-section="utility-bar"] .sl { gap: 14px; padding-left: 22px; border-left: 1px solid rgba(255,255,255,.18); }
@media (max-width: 1100px) { [data-bz-section="utility-bar"] .bz-col[data-bz-node="ub-right"] { display: none; } }
@media (max-width: 640px) { [data-bz-section="utility-bar"] .bz-block p { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } }

/* Footer */
[data-bz-section="site-footer"] .bz-block { padding-block: 0; }
[data-bz-section="site-footer"] .bz-block p { color: rgba(255,255,255,.66); font-size: 14px; line-height: 1.6; max-width: 46ch; }
[data-bz-section="site-footer"] .bz-nav--vertical { gap: 10px; }
[data-bz-section="site-footer"] .bz-navitem > a { font: 400 14px / 1.4 var(--font-body); color: rgba(255,255,255,.72); padding: 0; text-transform: none; letter-spacing: 0; }
[data-bz-section="site-footer"] .bz-navitem > a:hover { color: #fff; }
[data-bz-section="site-footer"] .bz-row[data-bz-node="ft-bottom"] { border-top: 1px solid rgba(255,255,255,.14); margin-top: 48px; padding-top: 22px; }
[data-bz-section="site-footer"] .bz-row[data-bz-node="ft-bottom"] p { font-size: 13px; margin: 0; }
[data-bz-section="site-footer"] .sl { margin-top: 22px; }
[data-bz-section="site-footer"] .bz-menu--vertical > .bz-nav { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
[data-bz-section="site-footer"] .bz-nav > .bz-navitem > .bz-navlabel { display: block; font: 700 13px / 1.3 var(--font-body); letter-spacing: .12em; text-transform: uppercase; color: #fff; margin: 0 0 14px; }
[data-bz-section="site-footer"] .bz-menu--vertical .bz-subnav { padding: 0; gap: 10px; }
@media (max-width: 640px) { [data-bz-section="site-footer"] .bz-menu--vertical > .bz-nav { grid-template-columns: minmax(0, 1fr); } [data-bz-section="site-footer"] .bz-subnav { min-width: 0; } }

/* Main menu: dark bar, white mega panel under it, phone number as a white pill.
   Panel photos are set here per trigger (1st Trucks, 2nd Trailers, 3rd Parts, 4th Service). */
[data-bz-node="main-nav"] .bz-nav { position: relative; display: flex; align-items: center; gap: 0; background: #262422; border: 1px solid rgba(255,255,255,.1); border-radius: 5px; padding: 3.5px 1px; }
[data-bz-node="main-nav"] .bz-nav > .bz-navitem { position: static; padding: 0 2px; }
[data-bz-node="main-nav"] .bz-nav > .bz-navitem > a { display: flex; align-items: center; height: 45px; font: 700 13px / 1 var(--font-body); text-transform: uppercase; letter-spacing: .1em; color: #fff; padding: 0 15.5px; border-radius: 2px; text-decoration: none; }
[data-bz-node="main-nav"] .bz-nav > .bz-navitem:hover > a, [data-bz-node="main-nav"] .bz-nav > .bz-navitem:focus-within > a, [data-bz-node="main-nav"] .bz-nav > .bz-navitem > a[aria-current="page"] { background: #41423f; color: #fff; text-decoration: underline; text-underline-offset: 4px; }
[data-bz-node="main-nav"] .bz-nav > .bz-navitem:last-child > a { background: #fff; color: var(--ink); margin-left: 8px; height: 40px; width: 137px; justify-content: center; white-space: nowrap; font-size: 13px; letter-spacing: .1em; text-decoration: none; border-radius: 5px; }
[data-bz-node="main-nav"] .bz-nav > .bz-navitem:last-child > a:hover { background: #ececea; }
/* The panel: anchored to the bar, as wide as it, white */
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav { left: -1px; right: -1px; top: calc(100% + 6px); transform: none; width: auto; max-width: none; min-width: 0; z-index: 70; justify-content: flex-start; flex-wrap: wrap; gap: 39px 40px; padding: 34px 283px 34px 35px; min-height: 358px; box-sizing: border-box; background: #fff; border: 0; border-radius: 3px; box-shadow: 0 24px 48px rgba(0,0,0,.28); }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav::before { content: ""; position: absolute; left: 0; right: 0; top: -12px; height: 12px; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-subnav > .bz-navitem > .bz-navlabel { font: 600 16px / 1.3 var(--font-body); letter-spacing: 0; text-transform: none; color: var(--ink); }
[data-bz-node="main-nav"] .bz-menu--mega .bz-subnav .bz-subnav { gap: 11.8px; margin-top: 9px; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-subnav .bz-subnav .bz-navitem > a { font: 400 16px / 1.3 var(--font-body); color: #222; text-transform: none; letter-spacing: 0; padding: 0; text-decoration: none; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-subnav .bz-subnav .bz-navitem > a:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 4px; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav > .bz-navitem { width: 193px; min-width: 0; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-subnav .bz-navitem { line-height: 1.3; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-subnav .bz-subnav .bz-navitem > a { display: block; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(-n+4) > .bz-subnav::after { content: ""; position: absolute; right: 33px; top: 50%; transform: translateY(-50%); width: 217px; height: 217px; border-radius: 3px; background: center / cover no-repeat; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1) > .bz-subnav::after { background-image: url("/images/hero-truck.webp"); }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(2) > .bz-subnav::after { background-image: url("/images/coverage-truck.webp"); }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(3) > .bz-subnav::after { background-image: url("/images/parts-showroom.webp"); }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(4) > .bz-subnav::after { background-image: url("/images/service-bay.webp"); }
@media (max-width: 1100px) {
  [data-bz-node="main-nav"] .bz-nav { background: none; border: 0; padding: 0; display: block; }
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav { min-width: 0; min-height: 0; padding: 12px 16px 20px; box-shadow: none; border-radius: 0; }
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav > .bz-navitem { width: auto; }
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem { padding: 0; }
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem > a { height: auto; display: block; }
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem:last-child > a { width: auto; height: auto; }
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(-n+4) > .bz-subnav::after { display: none; }
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem:last-child > a { display: inline-block; margin: 8px 0 0; }
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem > a { color: var(--ink); padding: 12px 8px; }
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem:hover > a, [data-bz-node="main-nav"] .bz-nav > .bz-navitem:focus-within > a { background: var(--paper); color: var(--ink); }
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem:last-child > a { background: var(--ink); color: #fff; }
}

/* Trucks panel: Shop Trucks over Shop Brands, Build & Finance beside them */
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1) > .bz-subnav { display: none; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1):hover > .bz-subnav, [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1):focus-within > .bz-subnav, [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1)[data-open] > .bz-subnav { display: grid; grid-template-columns: 193px 193px; grid-template-rows: auto auto; gap: 39px 40px; justify-content: start; align-items: start; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1) > .bz-subnav > .bz-navitem:nth-child(1) { grid-area: 1 / 1; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1) > .bz-subnav > .bz-navitem:nth-child(2) { grid-area: 1 / 2 / 3 / 3; }
[data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1) > .bz-subnav > .bz-navitem:nth-child(3) { grid-area: 2 / 1; }
@media (max-width: 1100px) { [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1):hover > .bz-subnav, [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1):focus-within > .bz-subnav, [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem:nth-child(1)[data-open] > .bz-subnav { display: flex; } }


/* Header over the page's hero image: when a page opens with a hero or banner the header is
   transparent and the image runs up behind it; once the page scrolls the header floats: no bar, no logo, just the menu pill (desktop, sticky pages). */
[data-bz-node="header"][data-bz-node] { padding-top: 14px; padding-bottom: 14px; }
@media (min-width: 1101px) {
  [data-bz-node="header"][data-bz-node]:has(+ main > [data-bz-node="hero"]:first-child), [data-bz-node="header"][data-bz-node]:has(+ main > [data-bz-node="banner"]:first-child) { padding-top: 30px; padding-bottom: 30px; margin-bottom: -114px; }
  [data-bz-node="header"][data-bz-node].bz-section--bg-ink:has(+ main > [data-bz-node="hero"]:first-child), [data-bz-node="header"][data-bz-node].bz-section--bg-ink:has(+ main > [data-bz-node="banner"]:first-child) { background: transparent; }
  .sr-sticky.sr-scrolled [data-bz-node="header"][data-bz-node].bz-section--bg-ink { background: transparent; pointer-events: none; top: 16px; }
  .sr-sticky.sr-scrolled [data-bz-node="header"][data-bz-node].bz-section--bg-ink:has(+ main > [data-bz-node="hero"]:first-child), .sr-scrolled [data-bz-node="header"][data-bz-node].bz-section--bg-ink:has(+ main > [data-bz-node="banner"]:first-child) { top: 0; }
  .sr-sticky.sr-scrolled [data-bz-node="header-brand"] { visibility: hidden; }
  .sr-sticky.sr-scrolled [data-bz-node="main-nav"] .bz-nav { pointer-events: auto; box-shadow: 0 10px 30px rgba(0,0,0,.28); }
  [data-bz-node="header"] + main > [data-bz-node="hero"]:first-child[data-bz-node] { padding-top: 150px; }
  [data-bz-node="header"] + main > [data-bz-node="banner"]:first-child[data-bz-node] { padding-top: 158px; }
}

/* Sticky header on the main site only. The template script adds .sr-sticky to <html>
   everywhere except the /store inventory pages, where the header scrolls. */
.sr-sticky [data-bz-node="header"] { position: sticky; top: 0; z-index: 60; }

/* Footer: "Built by BuzzNerd" in the middle of the bottom row */
[data-bz-section="site-footer"] .bz-col[data-bz-node="ft-builtby"] { display: flex; align-items: center; justify-content: center; gap: 10px; }
[data-bz-section="site-footer"] .bz-col[data-bz-node="ft-builtby"] .bz-block, [data-bz-section="site-footer"] .bz-col[data-bz-node="ft-builtby"] .bz-container, [data-bz-section="site-footer"] .bz-col[data-bz-node="ft-builtby"] figure { width: auto; margin: 0; padding: 0; }
[data-bz-section="site-footer"] [data-bz-node="ft-builtby-t"] p { margin: 0; white-space: nowrap; }
[data-bz-section="site-footer"] [data-bz-node="ft-builtby-logo"] img { display: block; height: 22px; width: auto; max-width: none; border-radius: 0; }
@media (max-width: 640px) { [data-bz-section="site-footer"] .bz-col[data-bz-node="ft-builtby"] { justify-content: flex-start; } }

