/* Sticky header on the main site only (see the template CSS, .sr-sticky).
   The storefront loads this script too, so it checks the address: under the
   storefront prefix (/store) the header is left to scroll with the page. */
(function () {
  var prefix = "/" + ((document.body && document.body.getAttribute("data-bz-prefix")) || "store");
  var path = location.pathname;
  var onStore = path === prefix || path.indexOf(prefix + "/") === 0;
  if (!onStore) document.documentElement.classList.add("sr-sticky");
})();

/* Main menu: Escape closes an open panel, and on touch (no hover) opening one
   panel closes the others and a tap outside closes them all. Hover and focus
   opening stay pure CSS. */
(function () {
  var nav = document.querySelector('[data-bz-node="main-nav"]');
  if (!nav) return;
  var items = nav.querySelectorAll('.bz-nav > .bz-navitem--has-sub');
  function closeAll() {
    Array.prototype.forEach.call(items, function (i) { i.removeAttribute('data-open'); });
    if (nav.contains(document.activeElement)) document.activeElement.blur();
  }
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') closeAll(); });
  document.addEventListener('click', function (e) {
    Array.prototype.forEach.call(items, function (i) { if (!i.contains(e.target)) i.removeAttribute('data-open'); });
  });
})();

/* Header over a hero image goes solid once the page has scrolled (see the template CSS, .sr-scrolled). */
(function () {
  var root = document.documentElement;
  function sync() { root.classList.toggle('sr-scrolled', (window.pageYOffset || root.scrollTop) > 8); }
  window.addEventListener('scroll', sync, { passive: true });
  sync();
})();
